unit.function:
@app.route("/BenchmarkTest00001", methods=["POST"])
def BenchmarkTest00001():
    env_value = os.environ.get('APP_INPUT', '')
    data = '%s' % (env_value,)
    base = Path('/var/app/data').resolve()
    candidate = (base / data).resolve()
    if base not in candidate.parents and candidate != base:
        return jsonify({'error': 'forbidden'}), 403
    checked_path = str(candidate)
    os.unlink(checked_path)
    return jsonify({"result": "success"})

@app.route("/BenchmarkTest00002", methods=["POST"])
def BenchmarkTest00002():
    json_value = (request.get_json(silent=True) or {}).get('payload', '')
    parts = str(json_value).split(',')
    data = ' '.join(parts)
    db.execute('SELECT * FROM users WHERE id = ?', (data,))
    return jsonify({"result": "success"})

@app.route("/BenchmarkTest00003", methods=["POST"])
def BenchmarkTest00003():
    db_value = db.fetch_one('SELECT name FROM users LIMIT 1')
    kind = 'json' if str(db_value).lstrip().startswith('{') else 'text'
    match kind:
        case 'json':
            data = str(db_value).strip()
        case _:
            data = str(db_value)
    return redirect(str(data))

